def make_transform(top_order, bot_order, bot_res, top_res='push'):
    def transform(grid):
        H,W=len(grid),len(grid[0])
        comps=components(grid)
        reach=[[False]*W for _ in range(H)]; dq=deque()
        for i in range(H):
            for j in (0,W-1):
                if grid[i][j]==0 and not reach[i][j]: reach[i][j]=True; dq.append((i,j))
        for j in range(W):
            for i in (0,H-1):
                if grid[i][j]==0 and not reach[i][j]: reach[i][j]=True; dq.append((i,j))
        while dq:
            y,x=dq.popleft()
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and grid[ny][nx]==0 and not reach[ny][nx]:
                    reach[ny][nx]=True; dq.append((ny,nx))
        out=[[0]*W for _ in range(H)]
        infos=[]
        for idx,cells in enumerate(comps):
            rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            closed=any(grid[i][j]==0 and not reach[i][j] for i in range(r0,r1+1) for j in range(c0,c1+1))
            infos.append(dict(top=r0,left=c0,closed=closed,n=len(cells),cells=cells,
                              r0=r0,r1=r1,c0=c0,c1=c1,bw=c1-c0+1))
        def draw(info,off,c0):
            h,w=info['r1']-info['r0']+1,info['c1']-info['c0']+1
            shape=[[0]*w for _ in range(h)]
            for y,x in info['cells']: shape[y-info['r0']][x-info['c0']]=grid[y][x]
            for y in range(h):
                for x in range(w):
                    if shape[y][x]: out[off+y][c0+x]=shape[y][x]
        def blocked(info,c0,off):
            h,w=info['r1']-info['r0']+1,info['c1']-info['c0']+1
            shape=[[0]*w for _ in range(h)]
            for y,x in info['cells']: shape[y-info['r0']][x-info['c0']]=grid[y][x]
            return any(out[off+y][c0+x] for y in range(h) for x in range(w) if shape[y][x])
        orders={'reading':lambda d:(d['top'],d['left']),
                'reverse':lambda d:(-d['top'],-d['left']),
                'size_f':lambda d:(d['n'],d['top'],d['left']),
                'size_r':lambda d:(d['n'],-d['top'],-d['left']),
                'col_f':lambda d:(d['left'],d['top']),
                'col_r':lambda d:(-d['left'],-d['top'])}
        for info in sorted([d for d in infos if d['closed']], key=orders[top_order]):
            h=info['r1']-info['r0']+1
            off=0
            while blocked(info,info['c0'],off): off+=1
            draw(info,off,info['c0'])
        for info in sorted([d for d in infos if not d['closed']], key=orders[bot_order]):
            h,w=info['r1']-info['r0']+1,info['c1']-info['c0']+1
            off0,c0=H-h,info['c0']
            options=[]
            # slide options with distance
            if bot_res in ('slide','mindisp_s','mindisp_p'):
                for dist in range(1,W):
                    found=False
                    for s in (-dist,dist):
                        nc=c0+s
                        if 0<=nc and nc+w<=W and not blocked(info,nc,off0):
                            options.append(('slide',dist,nc)); found=True
                    if found and bot_res=='slide': break
            # push options
            off=off0
            while blocked(info,c0,off): off-=1
            options.append(('push',off0-off,c0))
            if bot_res=='slide':
                if any(o[0]=='slide' for o in options): ch=[o for o in options if o[0]=='slide'][0]
                else: ch=options[0]
            elif bot_res=='push': ch=options[-1]
            elif bot_res=='mindisp_s': ch=min(options,key=lambda o:(o[1],0 if o[0]=='slide' else 1))
            else: ch=min(options,key=lambda o:(o[1],0 if o[0]=='push' else 1))
            if ch[0]=='slide': draw(info,off0,ch[2])
            else: draw(info,off,ch[2])
        return out
    return transform

