def transform2(grid, top_order, bot_order, bot_res):
    H,W=len(grid),len(grid[0])
    comps=components(grid)
    out=[[0]*W for _ in range(H)]
    infos=[]
    for cells in comps:
        rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        # closed: flood fill zeros
        seen=set(); dq=deque([(r0,c0)]) if grid[r0][c0]==0 else deque()
        # simpler: reuse global reach via fresh flood from border limited to bbox region
        reach=set(); dq=deque()
        for j in range(c0,c1+1):
            for i in (0,H-1):
                if grid[i][j]==0 and (i,j) not in reach: reach.add((i,j)); dq.append((i,j))
        for i in range(r0,r1+1):
            for j in (0,W-1):
                if grid[i][j]==0 and (i,j) not in reach: reach.add((i,j)); dq.append((i,j))
        while dq:
            y,x=dq.popleft()
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and grid[ny][nx]==0 and (ny,nx) not in reach:
                    reach.add((ny,nx)); dq.append((ny,nx))
        closed=any((i,j) not in reach for i in range(r0,r1+1) for j in range(c0,c1+1) if grid[i][j]==0)
        infos.append(dict(top=r0,left=c0,n=len(cells),closed=closed,cells=cells,
                          r0=r0,r1=r1,c0=c0,c1=c1,h=r1-r0+1,w=c1-c0+1,
                          color=grid[cells[0][0]][cells[0][1]]))
    def draw(info,off,c0):
        for y,x in info['cells']: out[off+y-info['r0']][c0+x-info['c0']]=grid[y][x]
    def blocked(info,c0,off):
        for y,x in info['cells']:
            yy,xx=off+y-info['r0'],c0+x-info['c0']
            if yy<0 or yy>=H or xx<0 or xx>=W or out[yy][xx]: return True
        return False
    orders={'reading':lambda d:(d['top'],d['left']),
            'reverse':lambda d:(-d['top'],-d['left']),
            'size_f':lambda d:(d['n'],d['top'],d['left']),
            'size_r':lambda d:(-d['n'],d['top'],d['left']),
            'col_f':lambda d:(d['left'],d['top']),
            'col_r':lambda d:(-d['left'],-d['top']),
            'colf_tie_f':lambda d:(d['left'],d['top']),
            'colf_tie_r':lambda d:(d['left'],-d['top']),
            'colr_tie_f':lambda d:(-d['left'],d['top']),
            'colr_tie_r':lambda d:(-d['left'],-d['top'])}
    for info in sorted([d for d in infos if d['closed']], key=orders[top_order]):
        off=0
        while blocked(info,info['c0'],off): off+=1
        draw(info,off,info['c0'])
    for info in sorted([d for d in infos if not d['closed']], key=orders[bot_order]):
        h,w=info['h'],info['w']; c0=info['c0']; off0=H-h
        opts=[]
        if bot_res in ('slide','ms','mp'):
            for dist in range(1,W):
                opts+=[('s',dist,c0+s) for s in(-dist,dist)
                       if 0<=c0+s and c0+s+w<=W and not blocked(info,c0+s,off0)]
                if opts and bot_res=='slide': break
        off=off0
        while blocked(info,c0,off): off-=1
        opts.append(('p',off0-off,c0))
        if bot_res=='slide': ch=[o for o in opts if o[0]=='s'][0] if any(o[0]=='s' for o in opts) else opts[0]
        elif bot_res=='push': ch=opts[-1]
        elif bot_res=='ms': ch=min(opts,key=lambda o:(o[1],o[0]=='p'))
        else: ch=min(opts,key=lambda o:(o[1],o[0]=='s'))
        draw(info, off if ch[0]=='p' else off0, ch[2])
    return out

